use serde_json::{json,Value};use crate::{storage::Database,optimization_engine,power_manager,game_sessions};
pub fn preview(mode:&str)->Result<Value,String>{if !["Safe","Balanced","Gaming"].contains(&mode){return Err("Perfil não suportado".into())}let mut actions=Vec::new();let mut unsupported=Vec::new();for(id,name)in [("visual.tooltip_animation","Animação das sugestões"),("visual.menu_animation","Animação dos menus"),("visual.client_animation","Animações da área de cliente")]{if mode=="Safe"&&id=="visual.client_animation"{continue}match optimization_engine::read(id){Ok(Some(old))if old!=0=>actions.push(json!({"id":id,"name":name,"previous":old,"next":0,"risk":"Baixo","benefit":"Reduz movimento decorativo; não garante ganhos de FPS","selected":true,"admin":false})),Ok(_)=>{},Err(error)=>unsupported.push(json!({"id":id,"reason":error}))}}
 if mode!="Safe"{let guid=if mode=="Gaming"{game_sessions::GAMING}else{game_sessions::BALANCED};match power_manager::plans(){Ok(plans)=>{if let Some(plan)=plans.as_array().and_then(|p|p.iter().find(|p|p["id"]==guid)){if plan["active"]!=true{actions.push(json!({"id":if mode=="Gaming"{"power.gaming"}else{"power.balanced"},"name":format!("Plano de energia: {}",plan["name"].as_str().unwrap_or(guid)),"previous":power_manager::active()?,"next":guid,"risk":"Moderado","benefit":if mode=="Gaming"{"Pode aumentar consumo, ruído e temperatura. Sem aumento de FPS garantido."}else{"Seleciona o plano Equilibrado existente; o comportamento depende do dispositivo."},"selected":false,"admin":false}));}}else{unsupported.push(json!({"id":"power.scheme","reason":"O plano associado ao perfil não está instalado. Não será criado nem simulado."}));}},Err(error)=>unsupported.push(json!({"id":"power.scheme","reason":error}))}}
 Ok(json!({"profile":mode,"actions":actions,"unsupported":unsupported,"security":"Sem alterações a segurança, atualizações, serviços críticos, clocks, voltagens ou BIOS"}))}
pub fn apply(db:&Database,id:&str,previous:Value)->Result<Value,String>{match id{"power.balanced"|"power.gaming"=>{let expected=previous.as_str().ok_or("Plano original inválido")?;power_manager::apply(db,if id=="power.gaming"{game_sessions::GAMING}else{game_sessions::BALANCED},expected)},_=>{let expected=previous.as_u64().filter(|v|*v<=1).ok_or("Preferência original inválida")?;optimization_engine::apply(db,id,Some(expected as u32))}}}
#[cfg(test)]mod tests{use super::*;#[test]fn no_unsupported_profile(){assert!(preview("TurboUnsafe").is_err());let db=Database::open(std::path::Path::new(":memory:")).unwrap();assert!(apply(&db,"security.disable",json!(1)).is_err());}}
